444	/// Given a buf and some bounds, if there is a line terminator at the end of
445	/// the given bounds in buf, then the bounds are trimmed to remove the line
446	/// terminator.
447	pub fn trim_line_terminator(
448	    searcher: &Searcher,
449	    buf: &[u8],
450	    line: &mut Match,
451	) {
452	    let lineterm = searcher.line_terminator();
453	    if lineterm.is_suffix(&buf[*line]) {
454	        let mut end = line.end() - 1;
455	        if lineterm.is_crlf() && end > 0 && buf.get(end - 1) == Some(&b'\r') {
456	            end -= 1;
457	        }
458	        *line = line.with_end(end);
459	    }
460	}
